(function(){
  const col={es:0,en:1,pt:2,fr:3,de:4}[LANG];
  document.documentElement.lang=LANG;
  if(!col){window.tr=s=>s;return}
  const exact=new Map(),pats=[],esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  for(const r of I18N){const k=r[0],v=r[col]||k;
    if(/\{\d+\}/.test(k)){const lab=[];
      const rx=new RegExp('^'+k.split(/(\{\d+\})/).map(p=>/^\{\d+\}$/.test(p)?(lab.push(p),'(.+?)'):esc(p)).join('')+'$');
      pats.push([rx,lab,v])}
    else exact.set(k,v)}
  pats.sort((a,b)=>b[0].source.replace(/\(\.\+\?\)/g,'').length-a[0].source.replace(/\(\.\+\?\)/g,'').length);
  const memo=new Map();
  function seg(s){const t=s.trim();if(!t||!/[A-Za-zÀ-ÿ]/.test(t))return s;
    let v=memo.get(t);
    if(v===undefined){v=exact.get(t);
      if(v===undefined)for(const [rx,lab,tv] of pats){const m=rx.exec(t);if(m){v=tv;lab.forEach((l,i)=>{const g=m[i+1];v=v.split(l).join(exact.get(g)??g)});break}}
      if(v===undefined){const c=t.lastIndexOf(': ');if(c>0){const a=exact.get(t.slice(0,c));if(a!==undefined)v=a+t.slice(c)}}
      if(v===undefined)v=null;
      if(memo.size>20000)memo.clear();memo.set(t,v)}
    return v===null?s:s.replace(t,v)}
  const tr=s=>s.indexOf('\n')<0&&s.indexOf(' · ')<0?seg(s):s.split(/(\n+| · )/).map((p,i)=>i%2?p:seg(p)).join('');
  window.tr=tr;
  const SKIP={SCRIPT:1,STYLE:1,TEXTAREA:1,INPUT:1};
  function txt(n){const v=n.nodeValue;if(v&&v.length<4000){const t=tr(v);if(t!==v)n.nodeValue=t}}
  function attrs(e){for(const a of ['title','placeholder','aria-label']){const v=e.getAttribute(a);if(v){const t=tr(v);if(t!==v)e.setAttribute(a,t)}}
    if(e.tagName==='INPUT'||e.tagName==='TEXTAREA'){const v=e.getAttribute('placeholder');if(v){const t=tr(v);if(t!==v)e.setAttribute('placeholder',t)}}}
  function walk(n){if(n.nodeType===3){txt(n);return}if(n.nodeType!==1)return;attrs(n);if(SKIP[n.tagName])return;
    for(let c=n.firstChild;c;c=c.nextSibling)walk(c)}
  new MutationObserver(ms=>{for(const m of ms){
    if(m.type==='characterData'){if(!m.target.parentNode||!SKIP[m.target.parentNode.tagName])txt(m.target)}
    else if(m.type==='attributes')attrs(m.target);
    else for(const n of m.addedNodes){if(n.nodeType===3&&n.parentNode&&SKIP[n.parentNode.tagName])continue;walk(n)}}})
   .observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','placeholder','aria-label']});
})();
function langMenu(btn){let m=document.getElementById('langMenu');if(m){m.remove();return}
  m=document.createElement('div');m.id='langMenu';
  m.innerHTML=LANGS.map(([c,n])=>`<button data-lang="${c}" class="${c===LANG?'on':''}"><i class="flag">${FLAGS[c]}</i><span translate="no">${n}</span></button>`).join('');
  document.body.appendChild(m);const r=btn.getBoundingClientRect();
  m.style.left=Math.max(8,r.left)+'px';m.style.bottom=(innerHeight-r.top+8)+'px';
  m.onclick=e=>{const b=e.target.closest('[data-lang]');if(!b)return;try{localStorage.setItem('flpm.lang',b.dataset.lang)}catch(x){}location.reload()};
  setTimeout(()=>document.addEventListener('click',function f(e){if(!m.contains(e.target)&&e.target!==btn&&!btn.contains(e.target)){m.remove();document.removeEventListener('click',f)}}),0)}
